__NUXT_JSONP__("/think-tanks/eventos/es_adverso_el_contexto_politico_que_enfrentan_los_think_tanks_en_mexico", (function(a,b,c,d,e,f,g,h,i){return {data:[{post:{slug:"es_adverso_el_contexto_politico_que_enfrentan_los_think_tanks_en_mexico",title:"Es adverso el contexto político que enfrentan los think tanks en México",date:"2023-12-05T21:59:19.630Z",img:"https:\u002F\u002Fucarecdn.com\u002Fd748eef7-77fc-47a5-831c-eb1c54f29cfe\u002F","img-alt":"Javier González Ethos",autor:"Ethos",category:"think-tanks",extracto:"Ante los retos que enfrentan los think tanks, sobre todo en México, es importante mantenerse fieles a los principios de verdad, objetividad, visión de largo plazo y neutralidad política, señaló Javier González en la presentación del Reporte del estado de los think tanks.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"En México y el mundo, los think tanks trabajan en un contexto político adverso, expresó Javier González, director de Desarrollo Institucional en Ethos, en la presentación del Reporte del estado de los think tanks, un informe anual elaborado por "},{type:b,tag:d,props:{href:"https:\u002F\u002Fonthinktanks.org\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"On Think Tanks"}]},{type:a,value:" que ofrece una visión general del sector. "}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"En el evento, que se llevó a cabo en Guadalajara, Jalisco, y en cuya organización participaron también "},{type:b,tag:d,props:{href:"https:\u002F\u002Ftransversalthinktank.org\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Transversal think tank"}]},{type:a,value:" y el "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.iteso.mx\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"ITESO Universidad Jesuita de Guadalajara"}]},{type:a,value:", compartió que desde hace 25 años que se incorporó a trabajar en asuntos públicos, no había percibido un clima tan poco propicio para las políticas basadas en evidencia."}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"Asimismo, resaltó 3 fuerzas o elementos del contexto político en México que complican la tarea de los think tanks, retomando una idea de Moisés Naím: la post verdad, es decir, hay menos pisos comunes o acuerdos básicos para tener diálogos constructivos, cada quien tiene su verdad; el populismo, con el desdén por los centro de investigación; y la polarización, ver como enemigo a quien no piensa como nosotros."}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"Ante este panorama, destacó que es importante mantenerse fieles a los principios de verdad, objetividad, visión de largo plazo y neutralidad política. También indicó que deben enfatizar su independencia y el sustento técnico de los argumentos; desarrollar habilidades de incidencia, formas de comunicar que tiendan puentes; y generar alianzas con otros think tanks."}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"En el evento también participaron David Gómez Álvarez, de Transversal Think Tank; Valeria Moy, del "},{type:b,tag:d,props:{href:"https:\u002F\u002Fimco.org.mx\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Instituto Mexicano para la Competitividad (IMCO) A.C"}]},{type:a,value:"; Radamanto Portilla Tinajero, del Departamento de Estudios Sociopolíticos y Jurídicos del ITESO, Universidad Jesuita de Guadalajara; y Sofía Ramírez, de "},{type:b,tag:d,props:{href:"https:\u002F\u002Fmexicocomovamos.mx\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"México, ¿cómo vamos?"}]}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fes_adverso_el_contexto_politico_que_enfrentan_los_think_tanks_en_mexico",extension:".md",createdAt:"2023-12-09T02:06:39.559Z",updatedAt:"2023-12-09T02:06:39.560Z"}}],fetch:{},mutations:[]}}("text","element","p","a","nofollow","noopener","noreferrer","_blank","\n")));